  "starship.toml": "# Fallback snapshot: starship prompt config (sanitized mirror of the live file).\n# Live source: ~/.config/starship.toml\n# Sanitization: hostname/username literals are replaced with generic styling —\n# never bundle host-identifying values. Structure mirrors the live config so\n# the Starship Playground renders a faithful prompt when the live file is absent.\n\nadd_newline = true\ncommand_timeout = 200\nformat = \"$username$hostname[$directory$git_branch$git_status$git_state${custom.git_dirty}]($style)$git_commit$character\"\n\n[character]\nerror_symbol = \"[❯](bold red)\"\nsuccess_symbol = \"[❯](bold cyan)\"\n\n[directory]\ntruncation_length = 2\ntruncation_symbol = \"…/\"\nstyle = \"bold cyan\"\nrepo_root_style = \"bold cyan\"\nrepo_root_format = \"[$repo_root]($repo_root_style)[$path]($style)[$read_only]($read_only_style) \"\n\n[git_branch]\nformat = \"[$symbol$branch]($style) \"\nstyle = \"italic cyan\"\n\n[git_status]\nstyle = \"cyan\"\nahead = \"⇡${count} \"\ndiverged = \"⇕⇡${ahead_count}⇣${behind_count} \"\nbehind = \"⇣${count} \"\nconflicted = \" \"\nup_to_date = \" \"\nuntracked = \"\"\nmodified = \"\"\nstashed = \"\"\nstaged = \"\"\nrenamed = \"\"\ndeleted = \"\"\n\n[custom.git_dirty]\ncommand = \"printf ''\"\nwhen = '''git status --porcelain --ignore-submodules=dirty | grep -Eq '^(\\?\\?|.[MT])' '''\nformat = \"[$output]($style) \"\nstyle = \"cyan\"\n\n[git_commit]\nonly_detached = true\ncommit_hash_length = 7\nformat = \"[($hash)]($style) \"\nstyle = \"italic dimmed cyan\"\n\n[git_state]\nformat = \"[($state( $progress_current/$progress_total))]($style) \"\nstyle = \"bold cyan\"\n\n[username]\nformat = \"[$user]($style)\"\nstyle_user = \"bold cyan\"\nstyle_root = \"bold cyan\"\n\n[hostname]\nssh_only = true\nformat = \"at [$hostname](bold dimmed cyan) \"\n"
